import { api } from '../lib/api.js';
import { dateParts, money, escapeHtml } from '../lib/format.js';
import { icon, setTitle } from '../lib/dom.js';

export async function eventsView() {
  setTitle('What’s happening next');
  const events = await api.listEvents();
  return {
    meta: { section: 'public' },
    html: `
      <main id="main" tabindex="-1">
        <section class="programme-head page-shell">
          <div>
            <p class="kicker">LAGOS / UPCOMING</p>
            <h1>What’s happening next</h1>
          </div>
          <p class="programme-head__note">Real dates. Clear prices. Your ticket lands in your inbox after payment.</p>
        </section>
        <section class="event-programme" aria-label="Upcoming events">
          ${events.map(eventRow).join('')}
        </section>
        <section class="dispatch page-shell">
          <p class="kicker">THE WEEKLY DISPATCH</p>
          <div class="dispatch__layout">
            <h2>Hear about the good ones before the group chat does.</h2>
            <form class="dispatch__form" data-dispatch>
              <label for="dispatch-email">Email address</label>
              <div><input id="dispatch-email" type="email" placeholder="you@example.com" required><button class="button button--ink" type="submit">Join the list ${icon('arrow')}</button></div>
              <p>One useful note a week. Leave whenever you like.</p>
            </form>
          </div>
        </section>
      </main>`,
    mount() {
      const form = document.querySelector('[data-dispatch]');
      const handler = (event) => {
        event.preventDefault();
        form.innerHTML = '<p class="dispatch__thanks"><strong>You’re on the list.</strong><br>We’ll send the next bill here.</p>';
      };
      form?.addEventListener('submit', handler);
      return () => form?.removeEventListener('submit', handler);
    },
  };
}

function eventRow(event, index) {
  const date = dateParts(event.startsAt);
  const availableTiers = event.tiers.filter((tier) => tier.remaining > 0);
  const minPrice = Math.min(...availableTiers.map((tier) => tier.priceMinor));
  const soldOut = availableTiers.length === 0;
  return `
    <article class="event-row" style="--event-accent:${event.accent}">
      <div class="event-row__number">${String(index + 1).padStart(2, '0')}</div>
      <div class="event-row__date"><strong>${date.day}</strong><span>${date.month}<br>${date.year}</span></div>
      <a href="/event/${encodeURIComponent(event.slug)}" data-link class="event-row__poster" aria-label="See ${escapeHtml(event.name)} tickets">
        <img src="${event.image}" alt="" loading="${index ? 'lazy' : 'eager'}">
        <span class="poster-stamp">${escapeHtml(event.code)}</span>
      </a>
      <div class="event-row__copy">
        <p class="kicker">${escapeHtml(event.eyebrow)}</p>
        <h2><a href="/event/${encodeURIComponent(event.slug)}" data-link>${escapeHtml(event.name)}</a></h2>
        <dl class="event-facts">
          <div><dt>${icon('calendar')} When</dt><dd>${date.weekday}, ${date.day} ${date.month} · ${date.time}</dd></div>
          <div><dt>${icon('pin')} Where</dt><dd>${escapeHtml(event.venue)}</dd></div>
        </dl>
      </div>
      <div class="event-row__price">
        ${soldOut ? '<span class="status-label status-label--sold">Sold out</span>' : `<span>From</span><strong>${money(minPrice)}</strong>${event.fee.mode !== 'none' ? '<small>+ booking fee</small>' : ''}`}
        <a class="arrow-link" href="/event/${encodeURIComponent(event.slug)}" data-link>${soldOut ? 'Event details' : 'See tickets'} ${icon('arrow')}</a>
      </div>
    </article>`;
}
